add_filter( 'style_loader_src', 'perfectpixel_remove_asset_version', 999 );
add_filter( 'script_loader_src', 'perfectpixel_remove_asset_version', 999 );

function perfectpixel_remove_asset_version( $src ) {
	if ( is_admin() || ! is_string( $src ) || false === strpos( $src, 'ver=' ) ) {
		return $src;
	}
	return remove_query_arg( 'ver', $src );
}
